class Node { int value; Node next; Node(int v) { value = v; } }
class LinkedListDemo {
    Node head;
    void add(int v) { Node n = new Node(v); if (head == null) head = n; else { Node cur = head; while (cur.next != null) cur = cur.next; cur.next = n; } }
    int[] toArray() { java.util.List<Integer> list = new java.util.ArrayList<>(); Node cur = head; while (cur != null) { list.add(cur.value); cur = cur.next; } return list.stream().mapToInt(i->i).toArray(); }
}

public static void main(String[] args) {
    LinkedListDemo ll = new LinkedListDemo();
    ll.add(1); ll.add(2);
    System.out.println(java.util.Arrays.toString(ll.toArray()));
}

