class StatsOuter {
    private double[] data;
    private StatsOuter(double[] d) { data = d; }
    private double calcAverage() { double sum = 0; for (double d : data) sum += d; return sum / data.length; }
    public static class Module {
        StatsOuter outer;
        public Module(double[] d) { outer = new StatsOuter(d); }
        public double average() { return outer.calcAverage(); }
    }
}

public static void main(String[] args) {
    StatsOuter.Module stats = new StatsOuter.Module(new double[]{1,2,3,4,5});
    System.out.println(stats.average());
}

interface Notifier { void notify(String msg); } // I: male, wyspecjalizowane interfejsy
class EmailNotifier implements Notifier { public void notify(String msg) { System.out.println("Email: " + msg); } } // S: jedna odpowiedzialnosc
class NotificationService { // D: zalezy od interfejsu (Notifier), nie konkretnej klasy
    private final Notifier notifier;
    NotificationService(Notifier n) { notifier = n; }
    public final void send(String msg) { notifier.notify(msg); } // O: closed for modification (final)
}

public static void main(String[] args) {
    new NotificationService(new EmailNotifier()).send("Test SOLID");
}
